import { merge } from "@lumeland/core/utils/object.ts";
import { concurrent } from "@lumeland/core/utils/concurrent.ts";
import { parseSrcset, searchLinks } from "@lumeland/core/utils/dom-links.ts";
import { walkUrls } from "@lumeland/core/utils/css-urls.ts";
// Default options
export const defaults = {
    fn: (url) => url,
};
/**
 * A plugin to modify all URLs found in HTML and CSS documents
 * @see https://lume.land/plugins/modify-urls/
 */
export function modifyUrls(userOptions) {
    const options = merge(defaults, userOptions);
    function replace(url, page, element) {
        return url ? options.fn(url, page, element) : "";
    }
    async function replaceSrcset(attr, page, element) {
        const replaced = [];
        for (const [url, rest] of parseSrcset(attr)) {
            replaced.push((await replace(url, page, element)) + rest);
        }
        return replaced.join(", ");
    }
    return (site) => {
        site.process([".html", ".css"], function processModifyUrls(pages) {
            return concurrent(pages, async (page) => {
                if (page.outputPath.endsWith(".css")) {
                    page.text = await walkUrls(page.text, async (url, type) => {
                        if (type === "url") {
                            return await replace(url, page);
                        }
                        return url;
                    });
                    return;
                }
                const { document } = page;
                for (const { element, attribute, value } of searchLinks(document)) {
                    if (attribute === "srcset" || attribute === "imagesrcset") {
                        element.setAttribute(attribute, await replaceSrcset(value, page, element));
                        continue;
                    }
                    element.setAttribute(attribute, await replace(value, page, element));
                }
            });
        });
    };
}
export default modifyUrls;
